import { MeshBasicNodeMaterial } from 'three/webgpu';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry } = ctx.THREE;
  const colors = {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10',
    ...(config.intent?.visualSpec?.colors ?? {}),
  };

  const root = new Group();
  root.name = config.id ?? 'collection-list-row';

  const resources = [];
  const animations = new Set();

  const addResource = (resource) => {
    resources.push(resource);
    return resource;
  };

  const surfaceMaterial = addResource(new MeshBasicNodeMaterial({
    color: colors.surface,
  }));
  const surface = new Mesh(
    addResource(new PlaneGeometry(5.9, 0.86)),
    surfaceMaterial,
  );
  surface.name = 'row-surface';
  surface.position.z = -0.02;
  root.add(surface);

  const metalMaterial = addResource(new MeshBasicNodeMaterial({
    color: colors.ink,
    transparent: true,
    opacity: 0.46,
  }));
  const metalPlane = new Mesh(
    addResource(new PlaneGeometry(5.82, 0.78)),
    metalMaterial,
  );
  metalPlane.name = 'brushed-metal-texture';
  metalPlane.position.z = 0.005;
  root.add(metalPlane);

  const dividerMaterial = addResource(new MeshBasicNodeMaterial({
    color: colors.paper,
    transparent: true,
    opacity: 0.2,
  }));
  const divider = new Mesh(
    addResource(new PlaneGeometry(5.35, 0.012)),
    dividerMaterial,
  );
  divider.name = 'subtle-divider';
  divider.position.set(0.12, -0.39, 0.025);
  root.add(divider);

  const edgeMaterial = addResource(new MeshBasicNodeMaterial({
    color: colors.accent,
    transparent: true,
    opacity: 0,
  }));
  const focusEdge = new Mesh(
    addResource(new PlaneGeometry(0.025, 0.7)),
    edgeMaterial,
  );
  focusEdge.name = 'accent-focus-edge';
  focusEdge.position.set(-2.84, 0, 0.04);
  root.add(focusEdge);

  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  for (const item of items) {
    if (!item || typeof item.text !== 'string') continue;

    const role = item.role ?? '';
    const isMeta = /meta|caption|label|subhead|body/i.test(role);
    const text = ctx.fontAtlas.createText(item.text, {
      fontSize: item.typography?.fontSize ?? (isMeta ? 22 : 38),
      color: isMeta ? colors.paper : colors.paper,
      align: 'left',
      maxWidthPx: 760,
      letterSpacingPx: isMeta ? 1.2 : 0,
    });

    text.name = `row-text-${role || 'content'}`;
    text.position.set(-2.52, isMeta ? -0.12 : 0.1, 0.055);
    root.add(text);
  }

  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((texture) => {
      metalMaterial.map = texture;
      metalMaterial.needsUpdate = true;
    }).catch(() => {});
  }

  const tweenTo = (target, vars) => {
    const tween = gsap.to(target, vars);
    animations.add(tween);
    tween.eventCallback('onComplete', () => animations.delete(tween));
    return tween;
  };

  const setFocus = (focused) => {
    tweenTo(edgeMaterial, {
      opacity: focused ? 1 : 0,
      duration: 0.18,
      ease: 'power2.out',
    });
  };

  root.userData.handlers = {
    hover(active = true) {
      if (typeof active === 'object') active = active.active ?? true;
      tweenTo(root.position, {
        y: active ? 0.15 : 0,
        duration: 0.3,
        ease: 'power3.out',
      });
      if (!active) setFocus(false);
    },

    hoverEnd() {
      tweenTo(root.position, {
        y: 0,
        duration: 0.3,
        ease: 'power3.out',
      });
    },

    focus() {
      setFocus(true);
    },

    blur() {
      setFocus(false);
    },

    click() {
      const press = gsap.timeline();
      animations.add(press);
      press
        .to(root.scale, {
          x: 0.97,
          y: 0.97,
          z: 0.97,
          duration: 0.12,
          ease: 'power2.out',
        })
        .to(root.scale, {
          x: 1,
          y: 1,
          z: 1,
          duration: 0.42,
          ease: 'back.out(2.2)',
        });

      press.eventCallback('onComplete', () => animations.delete(press));
      ctx.emit('hub-collection.select', {
        nodeId: config.id ?? 'collection-list-row',
      });
    },
  };

  root.userData.cleanup = () => {
    for (const animation of animations) animation.kill();
    animations.clear();

    for (const resource of resources) {
      if (resource && typeof resource.dispose === 'function') resource.dispose();
    }

    root.traverse((object) => {
      if (object.userData?.cleanup && object.userData.cleanup !== root.userData.cleanup) {
        object.userData.cleanup();
      }
    });
  };

  return root;
}
